"use client";
import {useState} from "react";
type Row={id:string;name:string;status:string;detail?:string};
export default function AdminCrudTable({title,rows,onAddLabel="Add record"}:{title:string;rows:Row[];onAddLabel?:string}){
 const [items,setItems]=useState(rows);
 const [editing,setEditing]=useState<string|null>(null);
 const [name,setName]=useState("");
 function add(){if(!name.trim())return;setItems([...items,{id:`local-${Date.now()}`,name,status:"ACTIVE"}]);setName("")}
 function remove(id:string){setItems(items.filter(x=>x.id!==id))}
 return <div className="card">
  <div style={{display:"flex",justifyContent:"space-between",alignItems:"center",gap:10}}>
   <h2>{title}</h2>
   <div style={{display:"flex",gap:8}}><input className="input" style={{margin:0,width:220}} value={name} onChange={e=>setName(e.target.value)} placeholder="New record name"/><button className="btn btn-primary" onClick={add}>{onAddLabel}</button></div>
  </div>
  <table className="market-table"><thead><tr><th>Name</th><th>Status</th><th>Actions</th></tr></thead><tbody>
   {items.map(x=><tr key={x.id}><td><b>{x.name}</b><br/><span className="muted">{x.detail||x.id}</span></td><td>{x.status}</td><td>
    <button className="btn" onClick={()=>setEditing(editing===x.id?null:x.id)}>{editing===x.id?"Close":"Edit"}</button>{" "}
    <button className="btn" onClick={()=>remove(x.id)}>Delete</button>
   </td></tr>)}
  </tbody></table>
 </div>
}